use clap::Parser;
use std::time::Instant;

mod anti_cheat;
mod loader;
mod runner;
mod scorer;

#[derive(Parser)]
#[command(name = "vector-db-benchmark")]
#[command(about = "Benchmark client for Vector DB evaluation")]
struct Cli {
    /// Server URL
    #[arg(long, default_value = "http://127.0.0.1:8080")]
    server_url: String,

    /// Number of concurrent query threads
    #[arg(long, default_value_t = 4)]
    concurrency: usize,

    /// Number of warmup queries
    #[arg(long, default_value_t = 1000)]
    warmup: usize,

    /// Path to base vectors JSON file
    #[arg(long)]
    base_vectors: String,

    /// Path to query vectors JSON file
    #[arg(long)]
    query_vectors: String,

    /// Path to ground truth JSON file
    #[arg(long)]
    ground_truth: String,

    /// Recall threshold (0.0 to 1.0)
    #[arg(long, default_value_t = 0.95)]
    recall_threshold: f64,

    /// Random seed for query shuffling
    #[arg(long, default_value_t = 42)]
    seed: u64,

    /// Batch size for bulk insert
    #[arg(long, default_value_t = 1000)]
    batch_size: usize,

    /// Maximum number of queries to run (0 = all)
    #[arg(long, default_value_t = 0)]
    max_queries: usize,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();
    let client = reqwest::Client::new();

    // 1. Load and insert base vectors
    eprintln!("Loading base vectors from {}...", cli.base_vectors);
    let base_vectors = loader::load_vectors_from_file(&cli.base_vectors).await?;
    eprintln!("Loaded {} base vectors, inserting...", base_vectors.len());
    let inserted = loader::bulk_insert_vectors(&client, &cli.server_url, &base_vectors, cli.batch_size).await?;
    eprintln!("Inserted {} vectors", inserted);

    // 2. Load query vectors and ground truth
    eprintln!("Loading query vectors from {}...", cli.query_vectors);
    let all_query_vectors = loader::load_vectors_from_file(&cli.query_vectors).await?;
    eprintln!("Loading ground truth from {}...", cli.ground_truth);
    let all_ground_truth = scorer::load_ground_truth(&cli.ground_truth).await?;

    // Apply max_queries limit if set
    let (query_vectors, ground_truth) = if cli.max_queries > 0 && cli.max_queries < all_query_vectors.len() {
        eprintln!("Limiting to {} queries (out of {})", cli.max_queries, all_query_vectors.len());
        let qv: Vec<_> = all_query_vectors.into_iter().take(cli.max_queries).collect();
        let gt: Vec<_> = all_ground_truth.into_iter().take(cli.max_queries).collect();
        (qv, gt)
    } else {
        (all_query_vectors, all_ground_truth)
    };

    // 3. Warmup
    eprintln!("Running {} warmup queries...", cli.warmup);
    runner::run_warmup(&client, &cli.server_url, &query_vectors, cli.warmup).await;

    // 4. Run benchmark queries
    eprintln!(
        "Running {} queries with concurrency {}...",
        query_vectors.len(),
        cli.concurrency
    );
    let start = Instant::now();
    let query_results = runner::run_queries(
        &client,
        &cli.server_url,
        &query_vectors,
        cli.concurrency,
        cli.seed,
    )
    .await;
    let duration_secs = start.elapsed().as_secs_f64();

    // 5. Compute results
    let result = scorer::compute_benchmark_result(
        &query_results,
        &ground_truth,
        duration_secs,
        cli.concurrency,
        cli.recall_threshold,
    );

    // 6. Anti-cheat detection
    let result_ids: Vec<Vec<u64>> = query_results
        .iter()
        .map(|qr| qr.results.iter().map(|r| r.id).collect())
        .collect();
    let anti_cheat = anti_cheat::detect_hardcoded_results(&result_ids);
    eprintln!("Anti-cheat: {}", anti_cheat.message);

    // 7. Output JSON to stdout
    let output = serde_json::json!({
        "benchmark": result,
        "anti_cheat": anti_cheat,
    });
    let json = serde_json::to_string_pretty(&output)?;
    println!("{}", json);

    Ok(())
}

use serde::{Deserialize, Serialize};
use std::collections::HashSet;
use std::path::Path;

use crate::runner::QueryResult;

/// A single ground truth entry: the pre-computed nearest neighbors for a query.
#[derive(Debug, Clone, Deserialize)]
pub struct GroundTruthEntry {
    pub query_id: usize,
    pub neighbors: Vec<u64>, // Top-100 nearest neighbor IDs
}

/// Complete benchmark result with all metrics.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct BenchmarkResult {
    pub qps: f64,
    pub total_queries: usize,
    pub duration_secs: f64,
    pub avg_latency_ms: f64,
    pub p50_latency_ms: f64,
    pub p95_latency_ms: f64,
    pub p99_latency_ms: f64,
    pub recall: f64,
    pub recall_threshold: f64,
    pub recall_passed: bool,
    pub concurrency: usize,
}

/// Calculate queries per second.
pub fn calculate_qps(total_queries: usize, duration_secs: f64) -> f64 {
    if duration_secs <= 0.0 {
        return 0.0;
    }
    total_queries as f64 / duration_secs
}

/// Calculate the p-th percentile from a mutable slice of latencies.
///
/// Sorts the slice in place and returns the value at the given percentile.
/// `p` should be in [0.0, 100.0].
pub fn calculate_percentile(latencies: &mut [f64], p: f64) -> f64 {
    if latencies.is_empty() {
        return 0.0;
    }
    latencies.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let rank = (p / 100.0) * (latencies.len() - 1) as f64;
    let lower = rank.floor() as usize;
    let upper = rank.ceil() as usize;
    if lower == upper {
        latencies[lower]
    } else {
        let frac = rank - lower as f64;
        latencies[lower] * (1.0 - frac) + latencies[upper] * frac
    }
}

/// Calculate average recall across all queries.
///
/// For each query, computes the intersection of the model's top-10 result IDs
/// with the ground truth top-10 IDs, divided by 10. Returns the average across
/// all queries.
pub fn calculate_recall(
    query_results: &[QueryResult],
    ground_truth: &[GroundTruthEntry],
) -> f64 {
    if query_results.is_empty() || ground_truth.is_empty() {
        return 0.0;
    }

    // Build a lookup from query_id -> ground truth neighbors
    let gt_map: std::collections::HashMap<usize, &Vec<u64>> = ground_truth
        .iter()
        .map(|gt| (gt.query_id, &gt.neighbors))
        .collect();

    let total_recall: f64 = query_results
        .iter()
        .filter_map(|qr| {
            let gt_neighbors = gt_map.get(&qr.query_index)?;
            let gt_top10: HashSet<u64> = gt_neighbors.iter().take(10).copied().collect();
            let model_top10: HashSet<u64> = qr.results.iter().take(10).map(|r| r.id).collect();
            let intersection = model_top10.intersection(&gt_top10).count();
            Some(intersection as f64 / 10.0)
        })
        .sum();

    let matched_count = query_results
        .iter()
        .filter(|qr| gt_map.contains_key(&qr.query_index))
        .count();

    if matched_count == 0 {
        return 0.0;
    }

    total_recall / matched_count as f64
}

/// Combine all calculations into a single BenchmarkResult.
pub fn compute_benchmark_result(
    query_results: &[QueryResult],
    ground_truth: &[GroundTruthEntry],
    duration_secs: f64,
    concurrency: usize,
    recall_threshold: f64,
) -> BenchmarkResult {
    let total_queries = query_results.len();
    let qps = calculate_qps(total_queries, duration_secs);

    let mut latencies: Vec<f64> = query_results.iter().map(|qr| qr.latency_ms).collect();
    let avg_latency_ms = if latencies.is_empty() {
        0.0
    } else {
        latencies.iter().sum::<f64>() / latencies.len() as f64
    };

    let p50 = calculate_percentile(&mut latencies, 50.0);
    let p95 = calculate_percentile(&mut latencies, 95.0);
    let p99 = calculate_percentile(&mut latencies, 99.0);

    let recall = calculate_recall(query_results, ground_truth);
    let recall_passed = recall >= recall_threshold;

    BenchmarkResult {
        qps,
        total_queries,
        duration_secs,
        avg_latency_ms,
        p50_latency_ms: p50,
        p95_latency_ms: p95,
        p99_latency_ms: p99,
        recall,
        recall_threshold,
        recall_passed,
        concurrency,
    }
}

/// Load ground truth entries from a JSON file.
pub async fn load_ground_truth(
    path: &str,
) -> Result<Vec<GroundTruthEntry>, Box<dyn std::error::Error>> {
    let path = Path::new(path);
    let content = tokio::fs::read_to_string(path).await?;
    let entries: Vec<GroundTruthEntry> = serde_json::from_str(&content)?;
    Ok(entries)
}

