58	async fn handle_search(State(db): State<Arc<VectorDB>>, body: Bytes) -> Response {
59	    if let Some(body) = db.cached_response_for_request(body.as_ref()) {
60	        return json_bytes_response(body);
61	    }
62	
63	    let req: SearchRequest = match serde_json::from_slice(&body) {
64	        Ok(req) => req,
65	        Err(_) => return StatusCode::BAD_REQUEST.into_response(),
66	    };
67	
68	    if let Some(body) = db.cached_response_body(&req.vector, req.top_k) {
69	        return json_bytes_response(body);
70	    }
71	
72	    let results = db.search(&req.vector, req.top_k);
73	    match serde_json::to_vec(&SearchResponse { results }) {
74	        Ok(body) => json_bytes_response(Bytes::from(body)),
75	        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
76	    }
