123	    pub fn bulk_insert(&self, vectors: Vec<(u64, Vec<f32>)>) -> usize {
124	        let mut inserted = 0usize;
125	        let mut raw = self.raw.write();
126	
127	        raw.ids.reserve(vectors.len());
128	        raw.vectors.reserve(vectors.len() * DIM);
