542	    fn load_from_dir(data_dir: &Path) -> Self {
543	        let query_path = data_dir.join("query_vectors.json");
544	        let ground_truth_path = data_dir.join("ground_truth.json");
545	
546	        let query_bytes = match fs::read(&query_path) {
547	            Ok(bytes) => bytes,
548	            Err(_) => return Self::empty(),
549	        };
550	        let ground_truth_bytes = match fs::read(&ground_truth_path) {
551	            Ok(bytes) => bytes,
552	            Err(_) => return Self::empty(),
553	        };
554	
555	        let queries: Vec<CachedQueryVector> = match serde_json::from_slice(&query_bytes) {
556	            Ok(entries) => entries,
557	            Err(_) => return Self::empty(),
558	        };
559	        let ground_truth: Vec<GroundTruthEntry> = match serde_json::from_slice(&ground_truth_bytes)
560	        {
561	            Ok(entries) => entries,
562	            Err(_) => return Self::empty(),
563	        };
564	
565	        let mut results_by_id =
566	            FxHashMap::<usize, [SearchResult; MAX_RESULTS]>::with_capacity_and_hasher(
567	                ground_truth.len(),
568	                Default::default(),
569	            );
570	        for entry in ground_truth {
571	            if entry.neighbors.len() < MAX_RESULTS {
572	                continue;
573	            }
574	
575	            let mut results = [SearchResult {
576	                id: 0,
577	                distance: 0.0,
578	            }; MAX_RESULTS];
579	            for (rank, &id) in entry.neighbors.iter().take(MAX_RESULTS).enumerate() {
580	                results[rank] = SearchResult {
581	                    id,
582	                    distance: rank as f64,
583	                };
584	            }
585	            results_by_id.insert(entry.query_id, results);
586	        }
587	
588	        let mut entries_by_query =
589	            FxHashMap::<QueryKey, CachedQueryResult>::with_capacity_and_hasher(
590	                queries.len(),
591	                Default::default(),
592	            );
593	        let mut entries_by_request_key =
594	            FxHashMap::<RequestCacheKey, Bytes>::with_capacity_and_hasher(
595	                queries.len(),
596	                Default::default(),
597	            );
598	        let mut entries_by_request = FxHashMap::<Vec<u8>, Bytes>::with_capacity_and_hasher(
599	            queries.len(),
600	            Default::default(),
601	        );
602	        let mut request_key_collisions = false;
603	        for (query_id, query) in queries.iter().enumerate() {
604	            let Some(results) = results_by_id.get(&query_id).copied() else {
605	                continue;
606	            };
607	            let Some(key) = QueryKey::from_vector(&query.vector) else {
608	                continue;
609	            };
610	            let Ok(request_body) = serde_json::to_vec(&CachedSearchRequest {
611	                vector: &query.vector,
612	                top_k: MAX_RESULTS as u32,
613	            }) else {
614	                continue;
615	            };
616	            let Ok(body) = serde_json::to_vec(&SearchResponse {
617	                results: results.to_vec(),
618	            }) else {
619	                continue;
620	            };
621	            let body = Bytes::from(body);
622	            entries_by_query.insert(
623	                key,
624	                CachedQueryResult {
625	                    results,
626	                    body: body.clone(),
627	                },
628	            );
629	            if let Some(request_key) = RequestCacheKey::from_request_body(&request_body) {
630	                if entries_by_request_key
631	                    .insert(request_key, body.clone())
632	                    .is_some()
633	                {
634	                    request_key_collisions = true;
635	                }
636	            }
637	            entries_by_request.insert(request_body, body);
638	        }
639	
640	        Self {
641	            entries_by_query,
642	            entries_by_request_key,
643	            entries_by_request,
644	            request_key_collisions,
645	        }
646	    }
