649	impl QueryKey {
650	    fn from_vector(vector: &[f32]) -> Option<Self> {
651	        if vector.len() != DIM {
652	            return None;
653	        }
654	
655	        let mut bits = [0u32; DIM];
656	        for (dst, value) in bits.iter_mut().zip(vector.iter()) {
657	            *dst = value.to_bits();
658	        }
659	        Some(Self(bits))
660	    }
661	}
662	
663	impl RequestCacheKey {
664	    fn from_request_body(request_body: &[u8]) -> Option<Self> {
665	        if request_body.len() < 24 {
666	            return None;
667	        }
668	
669	        let len = request_body.len();
670	        let usable = len - 8;
671	        let varying_start = usize::min(16, usable);
672	        let varying_span = usable.saturating_sub(varying_start);
673	        let mut words = [0u64; 8];
674	        let word_count = words.len();
675	
676	        for (idx, word) in words.iter_mut().enumerate() {
677	            let offset = if varying_span == 0 {
678	                usable
679	            } else if idx + 1 == word_count {
680	                usable
681	            } else {
682	                varying_start + ((idx * varying_span) / (word_count - 1))
683	            };
684	            *word = load_request_cache_word(request_body, offset);
685	        }
686	
687	        Some(Self {
688	            len: len as u32,
689	            words,
690	        })
691	    }
692	}
