694	#[inline(always)]
695	fn load_request_cache_word(bytes: &[u8], offset: usize) -> u64 {
696	    let start = usize::min(offset, bytes.len().saturating_sub(8));
697	    let mut word = [0u8; 8];
698	    word.copy_from_slice(&bytes[start..start + 8]);
699	    u64::from_le_bytes(word)
700	}
