702	fn collect_training_sample(vectors: &[f32], count: usize) -> Vec<f32> {
703	    let sample_count = usize::min(count, TRAINING_SAMPLES);
704	    let mut sample = Vec::with_capacity(sample_count * DIM);
705	
706	    if sample_count == 0 {
707	        return sample;
708	    }
709	
710	    let step = count as f64 / sample_count as f64;
711	    let mut cursor = 0.0f64;
712	
713	    for _ in 0..sample_count {
714	        let idx = usize::min(cursor as usize, count - 1);
715	        let start = idx * DIM;
716	        sample.extend_from_slice(&vectors[start..start + DIM]);
717	        cursor += step;
718	    }
719	
720	    sample
721	}
