251	    fn ensure_index(&self) -> Arc<HierarchicalIndex> {
252	        if !self.dirty.load(Ordering::Acquire) {
253	            if let Some(index) = self.index.read().as_ref().cloned() {
254	                return index;
255	            }
256	        }
257	
258	        let _guard = self.build_lock.lock();
259	        if !self.dirty.load(Ordering::Acquire) {
260	            if let Some(index) = self.index.read().as_ref().cloned() {
261	                return index;
262	            }
263	        }
264	
265	        let raw = self.raw.read();
266	        let count = raw.ids.len();
267	
268	        if count == 0 {
269	            let empty = Arc::new(HierarchicalIndex {
270	                primary_centroids: vec![0.0; PRIMARY_CLUSTERS * DIM],
271	                secondary_centroids: vec![0.0; PRIMARY_CLUSTERS * SECONDARY_CLUSTERS * DIM],
272	                cluster_offsets: vec![0; PRIMARY_CLUSTERS * SECONDARY_CLUSTERS + 1],
273	                cluster_ids: Vec::new(),
274	                cluster_vectors: Vec::new(),
275	            });
276	            *self.index.write() = Some(empty.clone());
277	            self.dirty.store(false, Ordering::Release);
278	            return empty;
279	        }
280	
281	        let training = collect_training_sample(&raw.vectors, count);
282	        let primary_centroids = run_kmeans(
283	            &training,
284	            training.len() / DIM,
285	            PRIMARY_CLUSTERS,
286	            PRIMARY_KMEANS_ITERS,
287	        );
288	
289	        let sample_primary_assignments: Vec<usize> = training
290	            .par_chunks_exact(DIM)
291	            .map(|sample| nearest_centroid(sample, &primary_centroids, PRIMARY_CLUSTERS))
292	            .collect();
293	
294	        let mut primary_buckets: Vec<Vec<f32>> =
295	            (0..PRIMARY_CLUSTERS).map(|_| Vec::new()).collect();
296	        for (sample_idx, &primary_id) in sample_primary_assignments.iter().enumerate() {
297	            let start = sample_idx * DIM;
298	            primary_buckets[primary_id].extend_from_slice(&training[start..start + DIM]);
299	        }
300	
301	        let secondary_chunks: Vec<Vec<f32>> = primary_buckets
302	            .into_par_iter()
303	            .enumerate()
304	            .map(|(primary_id, bucket)| {
305	                if bucket.is_empty() {
306	                    return duplicate_centroid(
307	                        &primary_centroids[primary_id * DIM..(primary_id + 1) * DIM],
308	                        SECONDARY_CLUSTERS,
309	                    );
310	                }
311	
312	                if bucket.len() / DIM <= SECONDARY_CLUSTERS {
313	                    return expand_bucket_centroids(
314	                        &bucket,
315	                        &primary_centroids[primary_id * DIM..(primary_id + 1) * DIM],
316	                    );
317	                }
318	
319	                run_kmeans(
320	                    &bucket,
321	                    bucket.len() / DIM,
322	                    SECONDARY_CLUSTERS,
323	                    SECONDARY_KMEANS_ITERS,
324	                )
325	            })
326	            .collect();
327	
328	        let mut secondary_centroids =
329	            Vec::with_capacity(PRIMARY_CLUSTERS * SECONDARY_CLUSTERS * DIM);
330	        for chunk in secondary_chunks {
331	            secondary_centroids.extend_from_slice(&chunk);
332	        }
333	
334	        let assignments: Vec<usize> = (0..count)
335	            .into_par_iter()
336	            .map(|idx| {
337	                let start = idx * DIM;
338	                let vector = &raw.vectors[start..start + DIM];
339	                let primary_id = nearest_centroid(vector, &primary_centroids, PRIMARY_CLUSTERS);
340	                let secondary_start = primary_id * SECONDARY_CLUSTERS * DIM;
341	                let secondary_id = nearest_centroid(
342	                    vector,
343	                    &secondary_centroids
344	                        [secondary_start..secondary_start + SECONDARY_CLUSTERS * DIM],
